# stkkms: source after b14-trials.sh on the liveboot root shell (B16-B18).
# Stops the greeter, runs supertuxkart --benchmark straight to KMS as root,
# then restarts the greeter. Usage: STK_TIMEOUT=600 stkkms <tag> <arm> <FD_MESA_DEBUG|->
stkkms() { local tag=$1 arm=$2 mode=$3 lib rc=0 l t0 t1 home; lib=$(libdir $arm); [ "$mode" = - ] && mode=; home=/run/stk-home-$tag; rm -rf $home; mkdir -p $home/.config/supertuxkart/config-0.10; cp $B14/stk-seed/*.xml $home/.config/supertuxkart/config-0.10/; systemctl stop phrog; sleep 3; echo "=== STKKMS $tag arm=$arm mode=${mode:-default} args=${STK_ARGS:-}"; echo "lib $(sha256sum $lib/libgallium-26.2.2.so | cut -c1-16)"; echo "before $(brief) phoc=$(pgrep -x phoc)"; t0=$(cut -d" " -f1 /proc/uptime); timeout -k 10s ${STK_TIMEOUT:-900}s env $CLEAN -u DISPLAY -u WAYLAND_DISPLAY HOME=$home XDG_RUNTIME_DIR=/run XDG_CACHE_HOME=$B14/stk-cache-root SDL_VIDEODRIVER=kmsdrm SDL_VIDEO_DRIVER=kmsdrm LD_LIBRARY_PATH=$lib:$B14/stk/root/usr/lib64 SUPERTUXKART_DATADIR=$B14/stk/root/usr/share/supertuxkart MESA_SHADER_CACHE_DISABLE=true FD_MESA_DEBUG=$mode $B14/stk/root/usr/bin/supertuxkart --no-start-screen --benchmark --no-sound ${STK_ARGS:-} > $R/$tag.stk 2>&1 & l=$!; sleep 20; p=$(pgrep -x supertuxkart | head -1); echo "LOADED $tag pid=$p $(grep -m1 -o "/[^ ]*libgallium[^ ]*" /proc/$p/maps 2>/dev/null)"; wait $l || rc=$?; t1=$(cut -d" " -f1 /proc/uptime); sleep 3; echo "RESULT $tag exit=$rc launch=$t0 end=$t1"; grep -h -E "Profiler|Frame count|renderer:|Fatal|fatal|rror" $R/$tag.stk | head -6; grep -h -E "Profiler|Frame count" $home/.config/supertuxkart/config-0.10/stdout.log 2>/dev/null | head -3; kevents $t0; echo "after $(brief)"; systemctl start phrog; echo "=== END $tag"; }
